import scipy.special

def shapley_kernel(M: int, s: int) -> float:
    # sはここではlen(s)
    if s == 0 or s == M:
        return 10000.0 # infが返るのを防ぐ
    return (M - 1) / (scipy.special.binom(M, s) * s * (M - s))



