[4] x=\rho \cos \phi, y=\rho \sin \phi のとき, 次のことを証明せよ.

(1) x \frac{\partial f}{\partial y}-y \frac{\partial f}{\partial x}=0 ならば, f(x, y) は \rho だけの関数である.

(2) x \frac{\partial f}{\partial x}+y \frac{\partial f}{\partial y}=0 ならば, f(x, y) は \phi だけの関数である.

(3) \frac{\partial^2 f}{\partial x^2}+\frac{\partial^2 f}{\partial y^2}=\frac{\partial^2 f}{\partial \rho^2}+\frac{1}{\rho} \frac{\partial f}{\partial \rho}+\frac{1}{\rho^2} \frac{\partial^2 f}{\partial \phi^2}

問題略解\begin{aligned}
& \rho=\sqrt{x^2+y^2}, \quad \phi = \arctan (y / x)\\
& \frac{\partial \rho}{\partial x} = \frac{x}{\rho}=\cos \phi, \quad \frac{\partial \rho}{\partial y} = \frac{y}{\rho}=\sin \phi \\
& \frac{\partial \phi}{\partial x} = -\frac{y}{\rho^2}= -\frac{\sin \phi}{\rho}, \quad \frac{\partial \phi}{\partial y}=\frac{x}{\rho^2}=\frac{\cos \phi}{\rho} \\
& \frac{\partial f}{\partial x}=\frac{\partial f}{\partial \rho} \frac{\partial \rho}{\partial x}+\frac{\partial f}{\partial \phi} \frac{\partial \phi}{\partial x}=\cos \phi \frac{\partial f}{\partial \rho}-\frac{\sin \phi}{\rho} \frac{\partial f}{\partial \phi} \\
& \frac{\partial f}{\partial y}=\frac{\partial f}{\partial \rho} \frac{\partial \rho}{\partial y}+\frac{\partial f}{\partial \phi} \frac{\partial \phi}{\partial y}=\sin \phi \frac{\partial f}{\partial \rho}+\frac{\cos \phi}{\rho} \frac{\partial f}{\partial \phi}
\end{aligned}

(1) x(\partial f / \partial y)-y(\partial f / \partial x)=\partial f / \partial \phi=0. よって, f は \phi によらず, \rho だけの関数.

(2) x(\partial f / \partial x)+y(\partial f / \partial y)=\rho(\partial f / \partial \rho)=0. よって, f は \rho によらず, \phi だけの関数.

(3)\begin{aligned}
\frac{\partial^2 f}{\partial x^2}= & \frac{\partial}{\partial x}\left(\frac{\partial f}{\partial x}\right)=\frac{\partial}{\partial \rho}\left(\frac{\partial f}{\partial x}\right) \cdot \frac{\partial \rho}{\partial x}+\frac{\partial}{\partial \phi}\left(\frac{\partial f}{\partial x}\right) \cdot \frac{\partial \phi}{\partial x} \\
= & \frac{\partial}{\partial \rho}\left(\cos \phi \frac{\partial f}{\partial \rho}-\frac{\sin \phi}{\rho} \frac{\partial f}{\partial \phi}\right) \cdot \cos \phi \\
& +\frac{\partial}{\partial \phi}\left(\cos \phi \frac{\partial f}{\partial \rho}-\frac{\sin \phi}{\rho} \frac{\partial f}{\partial \phi}\right)\left(-\frac{\sin \phi}{\rho}\right) \\
= & \cos ^2 \phi \frac{\partial^2 f}{\partial \rho^2}+\frac{2 \sin \phi \cos \phi}{\rho^2} \frac{\partial f}{\partial \phi}-\frac{2 \sin \phi \cos \phi}{\rho} \frac{\partial^2 f}{\partial \rho \partial \phi} \\
& +\frac{\sin ^2 \phi}{\rho} \frac{\partial f}{\partial \rho}+\frac{\sin ^2 \phi}{\rho^2} \frac{\partial^2 f}{\partial \phi^2}
\end{aligned}

同様にして,\begin{aligned}
\frac{\partial^2 f}{\partial y^2}= & \sin ^2 \phi \frac{\partial^2 f}{\partial \rho^2}-\frac{2 \sin \phi \cos \phi}{\rho^2} \frac{\partial f}{\partial \phi}+\frac{2 \sin \phi \cos \phi}{\rho} \frac{\partial^2 f}{\partial \rho \partial \phi} \\
& +\frac{\cos ^2 \phi}{\rho} \frac{\partial f}{\partial \rho}+\frac{\cos ^2 \phi}{\rho^2} \frac{\partial^2 f}{\partial \phi^2}
\end{aligned}

よって,\frac{\partial^2 f}{\partial x^2}+\frac{\partial^2 f}{\partial y^2}=\frac{\partial^2 f}{\partial \rho^2}+\frac{1}{\rho} \frac{\partial f}{\partial \rho}+\frac{1}{\rho^2} \frac{\partial^2 f}{\partial \phi^2}

