となる

よってx \frac{\partial f}{\partial y} -y \frac{\partial f}{\partial x} = 0なら、fは\phiで微分したとき変化がない定数ということなので、fは\rhoだけの関数

(3) \frac{\partial^2 f}{\partial x^2}+\frac{\partial^2 f}{\partial y^2}=\frac{\partial^2 f}{\partial \rho^2}+\frac{1}{\rho} \frac{\partial f}{\partial \rho}+\frac{1}{\rho^2} \frac{\partial^2 f}{\partial \phi^2}

考え方：2次の合成関数の偏導関数を求めていく\begin{aligned}
\frac{\partial^2 f}{\partial x^2}
&= \frac{\partial}{\partial x}\left(\frac{\partial f}{\partial x}\right)\\
&= \frac{\partial}{\partial x}\left( \frac{\partial f}{\partial \rho} \frac{\partial \rho}{\partial x}+\frac{\partial f}{\partial \phi} \frac{\partial \phi}{\partial x} \right)\\
&= \frac{\partial}{\partial \rho}\left(\frac{\partial f}{\partial x}\right) \cdot \frac{\partial \rho}{\partial x}+\frac{\partial}{\partial \phi}\left(\frac{\partial f}{\partial x}\right) \cdot \frac{\partial \phi}{\partial x} \\
\end{aligned}

ここで\frac{\partial \rho}{\partial x}や\frac{\partial \phi}{\partial x}を求めるために、\rho, \phiの関数型とその導関数を求める必要がある

Step 1. \rho, \phiの関数型の同定：\begin{aligned}
x^2 + y^2
&= \rho^2 \cos^2 \phi + \rho^2 \sin^2 \phi\\
&= \rho^2 \underbrace{ (\cos^2 \phi + \sin^2 \phi) }_{=1}
= \rho^2
\quad
&\to \rho = \sqrt{x^2 + y^2}
\\
\frac{y}{x} &= \frac{\rho \sin \phi}{\rho \cos \phi} = \tan \phi
\quad
&\to \phi = \arctan(\tan \phi) = \arctan \left(\frac{y}{x} \right)
\end{aligned}

よって\rho=\sqrt{x^2+y^2}, \quad \phi=\tan ^{-1}\left(\frac{y}{x}\right)

Step 2. \rho, \phiの偏導関数\frac{\partial \rho}{\partial x}=\frac{x}{\sqrt{x^2+y^2}} = \frac{x}{\rho} =\cos \phi
, \quad
\frac{\partial \rho}{\partial y}=\frac{y}{\sqrt{x^2+y^2}} = \frac{y}{\rho} =\sin \phi\frac{\partial \phi}{\partial x}=-\frac{y}{x^2+y^2}=-\frac{\sin \phi}{\rho}
, \quad
\frac{\partial \phi}{\partial y}=\frac{x}{x^2+y^2}=\frac{\cos \phi}{\rho}

導出\begin{aligned}
\frac{\partial \phi}{\partial x}
&= \frac{1}{1 + (y/x)^2}\cdot (-\frac{x'}{x^2} y)\\
&= -\frac{1}{1 + \frac{y^2}{x^2}} \frac{y}{x^2}\\
&= -\frac{1}{\frac{x^2 + y^2}{x^2}} \frac{y}{x^2}\\
&= -\frac{x^2}{x^2 + y^2} \frac{y}{x^2}\\
&= -\frac{y}{x^2+y^2}\\
&= -\frac{\sin \phi}{\rho}\\
\\
\frac{\partial \phi}{\partial y}
&= \frac{1}{1 + (y/x)^2}\cdot \frac{1}{x}\\
&= \frac{x}{x^2 + y^2}\\
&= \frac{\cos \phi}{\rho}\\
\end{aligned}

Step 3. fの偏導関数

合成関数の偏微分\begin{gathered}
\frac{\partial f}{\partial x}=\frac{\partial f}{\partial \rho} \frac{\partial \rho}{\partial x}+\frac{\partial f}{\partial \phi} \frac{\partial \phi}{\partial x} \\
\frac{\partial f}{\partial y}=\frac{\partial f}{\partial \rho} \frac{\partial \rho}{\partial y}+\frac{\partial f}{\partial \phi} \frac{\partial \phi}{\partial y}
\end{gathered}

に代入すると\begin{aligned}
& \frac{\partial f}{\partial x}=\frac{\partial f}{\partial \rho} \cos \phi-\frac{\partial f}{\partial \phi} \frac{\sin \phi}{\rho} \\
& \frac{\partial f}{\partial y}=\frac{\partial f}{\partial \rho} \sin \phi+\frac{\partial f}{\partial \phi} \frac{\cos \phi}{\rho}
\end{aligned}

Step 4. fの2次の偏導関数\begin{aligned}
\frac{\partial^2 f}{\partial x^2}
&= \frac{\partial}{\partial x}\left(\frac{\partial f}{\partial x}\right)\\
&= \frac{\partial}{\partial x}\left( \frac{\partial f}{\partial \rho} \frac{\partial \rho}{\partial x}+\frac{\partial f}{\partial \phi} \frac{\partial \phi}{\partial x} \right)\\
&= \frac{\partial}{\partial \rho}\left(\frac{\partial f}{\partial x}\right) \cdot \frac{\partial \rho}{\partial x}+\frac{\partial}{\partial \phi}\left(\frac{\partial f}{\partial x}\right) \cdot \frac{\partial \phi}{\partial x} \\
&= \frac{\partial}{\partial \rho}\left(\frac{\partial f}{\partial x}\right) \cdot \cos \phi + \frac{\partial}{\partial \phi}\left(\frac{\partial f}{\partial x}\right) \cdot \left( -\frac{\sin \phi}{\rho} \right) \\
&= \frac{\partial}{\partial \rho}\left( \frac{\partial f}{\partial \rho} \frac{\partial \rho}{\partial x}+\frac{\partial f}{\partial \phi} \frac{\partial \phi}{\partial x} \right) \cdot \cos \phi + \frac{\partial}{\partial \phi}\left( \frac{\partial f}{\partial \rho} \frac{\partial \rho}{\partial x}+\frac{\partial f}{\partial \phi} \frac{\partial \phi}{\partial x} \right) \cdot \left( -\frac{\sin \phi}{\rho} \right) \\
&= \frac{\partial}{\partial \rho}\left(\cos \phi \frac{\partial f}{\partial \rho}-\frac{\sin \phi}{\rho} \frac{\partial f}{\partial \phi}\right) \cdot \cos \phi
+ \frac{\partial}{\partial \phi}\left(\cos \phi \frac{\partial f}{\partial \rho}-\frac{\sin \phi}{\rho} \frac{\partial f}{\partial \phi}\right)\left(-\frac{\sin \phi}{\rho}\right) \\
&= \frac{\partial}{\partial \rho}\left(\cos^2 \phi \frac{\partial f}{\partial \rho}
\right)
- \frac{\partial}{\partial \rho} \left( \frac{\sin \phi \cos \phi}{\rho} \frac{\partial f}{\partial \phi}\right)
- \frac{\partial}{\partial \phi} \left( \frac{\sin \phi \cos \phi}{\rho} \frac{\partial f}{\partial \rho} \right)
+ \frac{\partial}{\partial \phi} \left( \frac{\sin^2 \phi}{\rho^2} \frac{\partial f}{\partial \phi}\right) \\
&= \cos^2 \phi \frac{\partial^2 f}{\partial \rho^2}
- \frac{\partial}{\partial \rho} \left( \frac{\sin \phi \cos\phi}{\rho} \frac{\partial f}{\partial \phi}\right) 
- \frac{\partial}{\partial \phi} \left( \frac{\sin \phi \cos \phi}{\rho} \frac{\partial f}{\partial \rho} \right)
+ \frac{\sin^2 \phi}{\rho^2} \frac{\partial^2 f}{\partial \phi^2} \\
&= \cos ^2 \phi \frac{\partial^2 f}{\partial \rho^2}+\frac{2 \sin \phi \cos \phi}{\rho^2} \frac{\partial f}{\partial \phi}-\frac{2 \sin \phi \cos \phi}{\rho} \frac{\partial^2 f}{\partial \rho \partial \phi}
+\frac{\sin ^2 \phi}{\rho} \frac{\partial f}{\partial \rho}+\frac{\sin ^2 \phi}{\rho^2} \frac{\partial^2 f}{\partial \phi^2} \\
\\
\end{aligned}

最後の2行がつながらないが、うまくやればいけそう？\begin{aligned}
\frac{\partial^2 f}{\partial y^2}
&= \frac{\partial }{\partial y} \left( \frac{\partial f}{\partial y} \right)\\
&= \frac{\partial }{\partial y} \left( \frac{\partial f}{\partial \rho} \frac{\partial \rho}{\partial y}+\frac{\partial f}{\partial \phi} \frac{\partial \phi}{\partial y} \right)\\
&= \frac{\partial}{\partial \rho}\left(\frac{\partial f}{\partial y}\right) \cdot \frac{\partial \rho}{\partial y}+\frac{\partial}{\partial \phi}\left(\frac{\partial f}{\partial y}\right) \cdot \frac{\partial \phi}{\partial y} \\
&= \frac{\partial}{\partial \rho}\left(\frac{\partial f}{\partial y}\right) \cdot \sin \phi + \frac{\partial}{\partial \phi}\left(\frac{\partial f}{\partial y}\right) \cdot \frac{\cos \phi}{\rho} \\
&= \frac{\partial}{\partial \rho}\left( \frac{\partial f}{\partial \rho} \frac{\partial \rho}{\partial y}+\frac{\partial f}{\partial \phi} \frac{\partial \phi}{\partial y} \right) \cdot \sin \phi + \frac{\partial}{\partial \phi}\left( \frac{\partial f}{\partial \rho} \frac{\partial \rho}{\partial y}+\frac{\partial f}{\partial \phi} \frac{\partial \phi}{\partial y} \right) \cdot \frac{\cos \phi}{\rho} \\
&= \frac{\partial}{\partial \rho} \left( \frac{\partial f}{\partial \rho} \sin \phi +\frac{\partial f}{\partial \phi} \frac{\cos \phi}{\rho} \right) \cdot \sin \phi
  + \frac{\partial}{\partial \phi} \left( \frac{\partial f}{\partial \rho} \sin \phi +\frac{\partial f}{\partial \phi} \frac{\cos \phi}{\rho} \right) \cdot \frac{\cos \phi}{\rho} \\
&= \sin ^2 \phi \frac{\partial^2 f}{\partial \rho^2}-\frac{2 \sin \phi \cos \phi}{\rho^2} \frac{\partial f}{\partial \phi}+\frac{2 \sin \phi \cos \phi}{\rho} \frac{\partial^2 f}{\partial \rho \partial \phi}
 + \frac{\cos ^2 \phi}{\rho} \frac{\partial f}{\partial \rho}+\frac{\cos ^2 \phi}{\rho^2} \frac{\partial^2 f}{\partial \phi^2}
\end{aligned}

Step 5. fの2次の偏導関数の和を求める\frac{\partial^2 f}{\partial x^2}+\frac{\partial^2 f}{\partial y^2}=\frac{\partial^2 f}{\partial \rho^2}\left(\cos ^2 \phi+\sin ^2 \phi\right)+\frac{\partial^2 f}{\partial \phi^2}\left(\frac{\sin ^2 \phi+\cos ^2 \phi}{\rho^2}\right)+\frac{1}{\rho} \frac{\partial f}{\partial \rho}

\cos ^2 \phi+\sin ^2 \phi=1のため\frac{\partial^2 f}{\partial x^2}+\frac{\partial^2 f}{\partial y^2}=\frac{\partial^2 f}{\partial \rho^2}+\frac{1}{\rho} \frac{\partial f}{\partial \rho}+\frac{1}{\rho^2} \frac{\partial^2 f}{\partial \phi^2}

ということらしい

