優先度付きキューは最短経路アルゴリズム（ダイクストラ法）で頻繁に使われる。コストの小さいノードから順に探索することで効率よく最短距離を求められる。

import heapq

def dijkstra(graph, start):
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    heap = [(0, start)]  # (コスト, ノード)

    while heap:
        cost, u = heapq.heappop(heap)
        if cost > dist[u]:
            continue
        for v, weight in graph[u]:
            new_cost = cost + weight
            if new_cost < dist[v]:
                dist[v] = new_cost
                heapq.heappush(heap, (new_cost, v))

    return dist

graph = {
    'A': [('B', 1), ('C', 4)],
    'B': [('C', 2), ('D', 5)],
    'C': [('D', 1)],
    'D': [],
}

dijkstra(graph, 'A')

スタート地点からゴールまで何ステップで到達できるか求める。1ステップで +1 か +2 だけ進める場合に、位置 0 から位置 n まで最短何ステップかかるか。

from collections import deque

def min_steps(goal):
    queue = deque([(0, 0)])  # (現在地, ステップ数)
    visited = {0}

    while queue:
        pos, steps = queue.popleft()
        if pos == goal:
            return steps
        for next_pos in [pos + 1, pos + 2]:
            if next_pos <= goal and next_pos not in visited:
                visited.add(next_pos)
                queue.append((next_pos, steps + 1))

print(min_steps(5))   # 3  (0→2→4→5)
print(min_steps(10))  # 5  (0→2→4→6→8→10)

