各ノードが最大2つの子（左・右）を持つ木。

class TreeNode:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

二分探索木 は、次の条件を満たす二分木：

左部分木の全ノードの値 < 根の値

右部分木の全ノードの値 > 根の値

この性質により、木が平衡であれば探索・挿入・削除が O(\log n) で行える。

操作：

insert(x): 値 x を挿入する（O(\log n)）

search(x): 値 x を検索する（O(\log n)）

delete(x): 値 x を削除する（O(\log n)）

class BST:
    def __init__(self):
        self.root = None

    def insert(self, val):
        self.root = self._insert(self.root, val)

    def _insert(self, node, val):
        if node is None:
            return TreeNode(val)
        if val < node.val:
            node.left = self._insert(node.left, val)
        elif val > node.val:
            node.right = self._insert(node.right, val)
        return node

    def search(self, val):
        return self._search(self.root, val)

    def _search(self, node, val):
        if node is None:
            return False
        if val == node.val:
            return True
        if val < node.val:
            return self._search(node.left, val)
        return self._search(node.right, val)

    def delete(self, val):
        self.root = self._delete(self.root, val)

    def _delete(self, node, val):
        if node is None:
            return None
        if val < node.val:
            node.left = self._delete(node.left, val)
        elif val > node.val:
            node.right = self._delete(node.right, val)
        else:
            # 子が0または1つの場合
            if node.left is None:
                return node.right
            if node.right is None:
                return node.left
            # 子が2つの場合：右部分木の最小値（中順後継）で置き換える
            successor = self._min_node(node.right)
            node.val = successor.val
            node.right = self._delete(node.right, successor.val)
        return node

    def _min_node(self, node):
        while node.left:
            node = node.left
        return node

    def inorder(self):
        return inorder(self.root)



bst = BST()
for v in [5, 3, 7, 1, 4, 6, 8]:
    bst.insert(v)

print("inorder:", bst.inorder())   # [1, 3, 4, 5, 6, 7, 8]
print("search 4:", bst.search(4))  # True
print("search 9:", bst.search(9))  # False

bst.delete(3)
print("3を削除後:", bst.inorder())  # [1, 4, 5, 6, 7, 8]

