def height(node):
    """木の高さ（葉のheightは0）"""
    if node is None:
        return -1
    return 1 + max(height(node.left), height(node.right))

def size(node):
    """木のノード数"""
    if node is None:
        return 0
    return 1 + size(node.left) + size(node.right)


