    else:
        print(f"{target} は存在しない")

最短経路そのものを復元したい場合は、各頂点の直前の頂点（predecessor）を記録しておく。

def dijkstra_with_path(graph: dict, start: int) -> tuple[dict, dict]:
    dist = defaultdict(lambda: float("inf"))
    prev = {}
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            new_dist = dist[u] + w
            if new_dist < dist[v]:
                dist[v] = new_dist
                prev[v] = u
                heapq.heappush(heap, (new_dist, v))

    return dict(dist), prev


def reconstruct_path(prev: dict, start: int, goal: int) -> list[int]:
    path = []
    v = goal
    while v != start:
        if v not in prev:
            return []  # 到達不能
        path.append(v)
        v = prev[v]
    path.append(start)
    return path[::-1]


dist, prev = dijkstra_with_path(graph, start=0)
path = reconstruct_path(prev, start=0, goal=3)
print(f"0 → 3 の最短経路: {' → '.join(map(str, path))}, 距離: {dist[3]}")

バックトラッキング（Backtracking） は、再帰的に候補を構築しながら、制約を満たさないと判明した時点で引き返す（バックトラック）全探索の手法

純粋な全列挙と異なり、枝刈り（pruning） によって探索空間を大幅に削減できるsolve(状態):
    if 完成:
        結果を記録
        return
    for 候補 in 次の選択肢:
        if 候補が制約を満たす:
            状態に候補を追加
            solve(次の状態)      # 再帰
            状態から候補を除去   # バックトラック

計算量はノード数Nとエッジ数Eに対し O(N + E) 。各ノードを高々1回訪問し、各エッジを高々1~2回訪問するため

def dfs(graph: dict[int, list[int]], start: int):
    visited = set()  # 訪問済みの頂点を記録する

    def _dfs(v):
        visited.add(v)
        print(f"到達したnode: {v}, {visited=}")

        for next_v in graph[v]:
            if next_v not in visited:
                _dfs(next_v)

    _dfs(start)


