class Strategy:
    def execute(self, data):
        pass

class Add(Strategy):
    def execute(self, data):
        return sum(data)

class Multiply(Strategy):
    def execute(self, data):
        result = 1
        for x in data: result *= x
        return result

def run(strategy: Strategy, data):
    return strategy.execute(data)

print(run(Add(), [1, 2, 3]))
print(run(Multiply(), [1, 2, 3]))

