class AccountBalanceProjection:
    def __init__(self):
        self.balances = {}

    def apply(self, event):
        acc_id = event["account_id"]
        if event["type"] == "MoneyDeposited":
            self.balances[acc_id] = self.balances.get(acc_id, 0) + event["amount"]
        elif event["type"] == "MoneyWithdrawn":
            self.balances[acc_id] = self.balances.get(acc_id, 0) - event["amount"]

